-- Development seed: fictional data from the prototype, for the LOCAL database only.
-- `supabase db reset` runs it; `supabase db push` never does. Never run it against the cloud project
-- (and never use `--include-seed`).
--
-- The book quotes are not invented: the prototype's "quotes" are the reading-club owner's own
-- margin notes, so they are seeded as kind = 'note'. No `quote` rows exist.

do $$
begin
  if exists (select 1 from auth.users where email not like '%@seed.example') then
    raise exception 'seed.sql refused: this database already has real users. The seed is for local development only.';
  end if;
end;
$$;


update public.profiles set role = 'admin' where id = '00000001-0000-4000-8000-000000000001';
update public.profiles set role = 'moderator' where id = '00000001-0000-4000-8000-000000000002';





