insert into public.books (id, slug, title, author, synopsis, genres, total_chapters, current_chapter, status, rating, started_at, finished_at) values
  ('00000002-0000-4000-8000-000000000001', 'o-livro-de-azrael', 'O Livro de Azrael', 'Amber V. Nicole', 'Há mil anos, Dianna entregou a própria vida a Kaden, um monstro pior que qualquer pesadelo, para salvar a irmã. Desde então ela cumpre as ordens dele, inclusive caçar uma relíquia antiga. Do outro lado está Liam, o rei que um dia foi chamado de Samkiel e que deu as costas à própria coroa. Inimigos mais velhos que o tempo, os dois vão precisar um do outro.', array['Fantasia sombria','Romantasia','Inimigos para amantes']::text[], 52, 12, 'reading', null, '2026-09-02', null),
  ('00000002-0000-4000-8000-000000000002', 'a-ultima-carta-de-lisboa', 'A Última Carta de Lisboa', 'Tomás Reis', null, '{}', 38, 38, 'finished', 4.5, '2026-07-20', '2026-08-30'),
  ('00000002-0000-4000-8000-000000000003', 'o-silencio-das-baleias', 'O Silêncio das Baleias', 'Ingrid Sato', null, '{}', 34, 34, 'finished', 5, '2026-06-14', '2026-07-28'),
  ('00000002-0000-4000-8000-000000000004', 'noites-de-ambar', 'Noites de Âmbar', 'Clara Menezes', null, '{}', 41, 41, 'finished', 4, '2026-05-10', '2026-06-25'),
  ('00000002-0000-4000-8000-000000000005', 'cartografia-do-afeto', 'Cartografia do Afeto', 'Rafael Duarte', null, '{}', 30, 30, 'finished', 3.5, '2026-04-12', '2026-05-22'),
  ('00000002-0000-4000-8000-000000000006', 'sal-e-cinza', 'Sal e Cinza', 'Beatriz Lemos', null, '{}', 36, 36, 'finished', 4, '2026-03-08', '2026-04-20');
insert into public.reading_sessions (id, book_id, number, chapter_from, chapter_to, title, body, excerpt, rating, visibility, status, published_at, read_minutes) values
  ('00000003-0000-4000-8000-000000000004', '00000002-0000-4000-8000-000000000001', 4, 10, 12, 'Faíscas, farpas e uma trégua frágil', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Gente, que sessão. Li os capítulos 10, 11 e 12 numa sentada só, de madrugada, com chá e zero condição emocional. Se o começo do livro foi apresentando o mundo, agora ele começou a apresentar o problema: esses dois juntos."}]}, {"type": "chapterDivider", "attrs": {"chapter": 10, "title": "Ninguém aqui confia em ninguém"}}, {"type": "paragraph", "content": [{"type": "text", "text": "O que mais gosto na forma como a Amber escreve a Dianna é que ela nunca tenta ser simpática. É afiada, desconfiada e engraçada no pior momento possível. Passei metade do capítulo rindo e a outra metade tensa."}]}, {"type": "blockquote", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Dianna não pede desculpa por existir. Eu quero ser assim quando crescer."}]}]}, {"type": "chapterDivider", "attrs": {"chapter": 11, "title": "O peso de uma coroa abandonada"}}, {"type": "paragraph", "content": [{"type": "text", "text": "O Liam continua sendo um mistério pra mim. Dá pra sentir o luto dele em cada fala, mesmo quando tenta parecer frio. A autora não entrega tudo de uma vez, e estou gostando de montar esse quebra-cabeça devagar."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "A pergunta que ficou martelando: um rei que desistiu de tudo ainda pode ser chamado de rei?"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Minha teoria (achismo puro, sem spoiler): a relíquia que todo mundo está caçando vai custar muito mais do que a Dianna imagina, e desconfio que o Kaden sabe disso desde o começo.", "marks": [{"type": "italic"}]}]}, {"type": "chapterDivider", "attrs": {"chapter": 12, "title": "A irmã como bússola"}}, {"type": "paragraph", "content": [{"type": "text", "text": "Tudo o que a Dianna faz tem um motivo, e o motivo tem nome: Gabby. Essa parte me lembrou por que a gente perdoa tanta coisa nela. Ela não luta por poder, luta por alguém."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Fechei a sessão com a sensação de que o livro virou a chave. Sai a apresentação, entra o conflito de verdade."}]}]}'::jsonb, 'Dianna e Liam no mesmo ambiente é garantia de faísca. Esses três capítulos me deixaram dividida entre torcer por eles e querer que os dois se matem.', 4.5, 'public', 'published', '2026-09-27 10:00:00-03', 6),
  ('00000003-0000-4000-8000-000000000003', '00000002-0000-4000-8000-000000000001', 3, 7, 9, 'Inimigos mais velhos que o tempo', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Confesso: nos primeiros capítulos me perdi um pouco com tantos nomes. Nesta sessão as peças começaram a se encaixar."}]}, {"type": "chapterDivider", "attrs": {"chapter": 7, "title": "Um mundo em camadas"}}, {"type": "paragraph", "content": [{"type": "text", "text": "Reinos, raças e uma guerra antiga que ainda respira. Comecei um mapinha no caderno pra não me perder, e recomendo muito."}]}, {"type": "chapterDivider", "attrs": {"chapter": 8, "title": "Rancor de mil anos"}}, {"type": "paragraph", "content": [{"type": "text", "text": "O que torna essa rivalidade interessante é que nenhum dos dois está totalmente errado. Cada um carrega uma versão da história em que o outro é o monstro."}]}, {"type": "blockquote", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Inimigos por herança, não por escolha. Acho que o livro inteiro vai girar em torno disso."}]}]}, {"type": "chapterDivider", "attrs": {"chapter": 9, "title": "Kaden"}}, {"type": "paragraph", "content": [{"type": "text", "text": "Toda vez que o Kaden aparece o clima muda. Não sei explicar, mas a página fica mais fria."}]}]}'::jsonb, 'Deuses, monstros e mil anos de rancor. O mundo da Amber V. Nicole é enorme, e nesta sessão finalmente comecei a me localizar nele.', 4, 'public', 'published', '2026-09-20 10:00:00-03', 5),
  ('00000003-0000-4000-8000-000000000002', '00000002-0000-4000-8000-000000000001', 2, 4, 6, 'O rei que não queria ser rei', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Se a primeira sessão foi da Dianna, essa foi dele."}]}, {"type": "chapterDivider", "attrs": {"chapter": 4, "title": "Dois nomes, uma pessoa"}}, {"type": "paragraph", "content": [{"type": "text", "text": "Liam e Samkiel. Adorei como o nome muda conforme o peso que se quer dar a ele. Diz muito sobre quem ele foi e quem tenta ser agora."}]}, {"type": "chapterDivider", "attrs": {"chapter": 5, "title": "O cansaço"}}, {"type": "paragraph", "content": [{"type": "text", "text": "Ele não é o herói empolgado de sempre. É alguém exausto, e isso me pegou de jeito."}]}, {"type": "blockquote", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Um herói que perdeu a vontade de ser herói. Adoro quando um livro começa por aí."}]}]}, {"type": "chapterDivider", "attrs": {"chapter": 6, "title": "O chamado"}}, {"type": "paragraph", "content": [{"type": "text", "text": "Fica a sensação de que ele não vai conseguir fugir por muito tempo. Arrepiei."}]}]}'::jsonb, 'Conhecemos o Liam, ou Samkiel, dependendo de quem conta a história. Um rei cansado de ser rei, e eu já quero saber tudo sobre ele.', 4, 'public', 'published', '2026-09-13 10:00:00-03', 4),
  ('00000003-0000-4000-8000-000000000001', '00000002-0000-4000-8000-000000000001', 1, 1, 3, 'Primeiras impressões: Dianna', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Todo mundo me falou desse livro, e finalmente comecei. Spoiler sem spoiler: já estou envolvida."}]}, {"type": "chapterDivider", "attrs": {"chapter": 1, "title": "Uma protagonista sem filtro"}}, {"type": "paragraph", "content": [{"type": "text", "text": "A Dianna é intensa, irônica e perigosa, e o livro não pede desculpa por isso. Fazia tempo que eu não lia uma personagem tão cheia de arestas."}]}, {"type": "chapterDivider", "attrs": {"chapter": 2, "title": "O pacto"}}, {"type": "paragraph", "content": [{"type": "text", "text": "Saber desde o início que ela se entregou a alguém pra salvar a irmã muda a forma como a gente lê cada escolha dela. Tudo tem um preço."}]}, {"type": "chapterDivider", "attrs": {"chapter": 3, "title": "O tom"}}, {"type": "paragraph", "content": [{"type": "text", "text": "Fantasia sombria com humor no meio do caos. Deu vontade de ler até de manhã, e foi exatamente o que eu fiz."}]}]}'::jsonb, 'Começamos! Livro novo, marcador novo e uma protagonista que não pede licença. A escrita da Amber V. Nicole me ganhou nas primeiras páginas.', 4.5, 'public', 'published', '2026-09-06 10:00:00-03', 5);
