insert into public.session_questions (session_id, text, position) values
  ('00000003-0000-4000-8000-000000000004', 'A Dianna é vilã, anti-heroína ou só alguém sem saída?', 0),
  ('00000003-0000-4000-8000-000000000004', 'O que vocês acham que o Liam ainda esconde?', 1),
  ('00000003-0000-4000-8000-000000000004', 'Até aqui: time Dianna ou time Liam?', 2),
  ('00000003-0000-4000-8000-000000000003', 'Vocês estão fazendo anotações ou mapas para acompanhar o mundo?', 0),
  ('00000003-0000-4000-8000-000000000003', 'O que mais chamou atenção no worldbuilding até aqui?', 1),
  ('00000003-0000-4000-8000-000000000002', 'Primeira impressão do Liam: vocês confiam nele?', 0),
  ('00000003-0000-4000-8000-000000000001', 'A Dianna funcionou pra vocês logo de cara?', 0);
insert into public.comments (id, session_id, author_id, parent_id, body, read_up_to, spoiler_up_to, status, flag_reason, created_at) values
  ('00000004-0000-4000-8000-000000000001', '00000003-0000-4000-8000-000000000004', '00000001-0000-4000-8000-000000000002', null, 'O capítulo 10 foi puro caos e eu amei cada linha. A Dianna respondendo tudo com deboche é o meu tipo de protagonista.', 12, null, 'approved', null, '2026-09-29 12:00:00-03'),
  ('00000004-0000-4000-8000-000000000004', '00000003-0000-4000-8000-000000000004', '00000001-0000-4000-8000-000000000003', null, 'Discordo um pouco da teoria da relíquia. Acho que o preço maior não vai ser pra Dianna, e sim pra quem estiver do lado dela.', 12, null, 'approved', null, '2026-09-29 09:00:00-03'),
  ('00000004-0000-4000-8000-000000000006', '00000003-0000-4000-8000-000000000004', '00000001-0000-4000-8000-000000000004', null, 'Adiantei um pouquinho (desculpa!!). Só digo: segurem o coração nos próximos capítulos, e prestem atenção em quem a Dianna escolhe proteger.', 16, 15, 'approved', null, '2026-09-29 08:00:00-03'),
  ('00000004-0000-4000-8000-000000000007', '00000003-0000-4000-8000-000000000004', '00000001-0000-4000-8000-000000000005', null, 'Ainda estou no 10, mas vim dizer que estou fazendo o mapinha que a Agatha sugeriu e ele está salvando minha vida.', 10, null, 'approved', null, '2026-09-29 06:00:00-03'),
  ('00000004-0000-4000-8000-000000000008', '00000003-0000-4000-8000-000000000004', '00000001-0000-4000-8000-000000000006', null, 'Sobre a pergunta 1: pra mim ela é anti-heroína. Tudo o que ela faz tem um motivo, e o motivo é a irmã.', 12, null, 'approved', null, '2026-09-28 20:00:00-03'),
  ('00000004-0000-4000-8000-000000000009', '00000003-0000-4000-8000-000000000003', '00000001-0000-4000-8000-000000000008', null, 'Os nomes me confundiram no começo, mas agora estou viciada nesse mundo.', 12, null, 'approved', null, '2026-09-20 15:00:00-03'),
  ('00000004-0000-4000-8000-000000000010', '00000003-0000-4000-8000-000000000003', '00000001-0000-4000-8000-000000000003', null, 'O Kaden me dá arrepio toda vez que aparece.', 9, null, 'approved', null, '2026-09-21 11:00:00-03'),
  ('00000004-0000-4000-8000-000000000011', '00000003-0000-4000-8000-000000000002', '00000001-0000-4000-8000-000000000002', null, 'Liam entrou em cena e eu já fiquei assim 👀', 6, null, 'approved', null, '2026-09-13 14:00:00-03'),
  ('00000004-0000-4000-8000-000000000012', '00000003-0000-4000-8000-000000000002', '00000001-0000-4000-8000-000000000006', null, 'Um herói cansado é muito mais interessante que um herói perfeito.', 6, null, 'approved', null, '2026-09-14 09:00:00-03'),
  ('00000004-0000-4000-8000-000000000013', '00000003-0000-4000-8000-000000000001', '00000001-0000-4000-8000-000000000007', null, 'Comecei hoje e já estou apaixonada pela Dianna!', 3, null, 'approved', null, '2026-09-06 18:00:00-03'),
  ('00000004-0000-4000-8000-000000000014', '00000003-0000-4000-8000-000000000001', '00000001-0000-4000-8000-000000000005', null, 'Primeira vez participando do clube. Que ideia boa ter as sessões por capítulo.', 3, null, 'approved', null, '2026-09-07 10:00:00-03'),
  ('00000004-0000-4000-8000-000000000015', '00000003-0000-4000-8000-000000000004', '00000001-0000-4000-8000-000000000009', null, 'Alguém mais achou o capítulo 12 mais lento? Senti falta de mais cenas dos dois juntos.', 12, null, 'pending', null, '2026-09-29 23:48:00-03'),
  ('00000004-0000-4000-8000-000000000016', '00000003-0000-4000-8000-000000000004', '00000001-0000-4000-8000-000000000010', null, 'Já li a série inteira. O final desse primeiro livro vai destruir vocês, se preparem.', 12, null, 'pending', 'Possível spoiler do fim do livro', '2026-09-29 23:20:00-03'),
  ('00000004-0000-4000-8000-000000000017', '00000003-0000-4000-8000-000000000003', '00000001-0000-4000-8000-000000000011', null, 'Voltei nessa sessão depois de ler a 4 e agora tudo faz sentido!', 12, null, 'pending', null, '2026-09-29 21:00:00-03'),
  ('00000004-0000-4000-8000-000000000018', '00000003-0000-4000-8000-000000000004', '00000001-0000-4000-8000-000000000012', null, 'Compre livros com 90% de desconto clicando no link do perfil!!!', 0, null, 'pending', 'Provável spam', '2026-09-29 20:00:00-03'),
  ('00000004-0000-4000-8000-000000000019', '00000003-0000-4000-8000-000000000004', '00000001-0000-4000-8000-000000000013', null, 'Primeira vez comentando aqui. Comecei a ler por causa desse blog e estou amando 💗', 12, null, 'pending', null, '2026-09-29 18:00:00-03'),
  ('00000004-0000-4000-8000-000000000002', '00000003-0000-4000-8000-000000000004', '00000001-0000-4000-8000-000000000001', '00000004-0000-4000-8000-000000000001', 'Mari, eu ri alto de madrugada e tive que tapar a boca 😂', 12, null, 'approved', null, '2026-09-29 13:00:00-03'),
  ('00000004-0000-4000-8000-000000000003', '00000003-0000-4000-8000-000000000004', '00000001-0000-4000-8000-000000000008', '00000004-0000-4000-8000-000000000001', 'E reparem como o Liam fala pouco, mas cada frase dele pesa. A autora sabe o que está fazendo.', 12, null, 'approved', null, '2026-09-29 13:15:00-03'),
  ('00000004-0000-4000-8000-000000000005', '00000003-0000-4000-8000-000000000004', '00000001-0000-4000-8000-000000000007', '00000004-0000-4000-8000-000000000004', 'Pedro, não fala assim, eu tenho sentimentos 😭', 12, null, 'approved', null, '2026-09-29 10:00:00-03');
